// Human Approval & Exception Gate — input validation.
// Hard-fails on incomplete input. The gate must never open on partial data.

const REQUIRED = [
  'workflow_name', 'submission_id', 'review_type', 'system_status', 'confidence',
  'discrepancies', 'missing_information', 'evidence', 'recommended_human_action',
];

// Deliberately excludes PASS / CLEARED / APPROVED / CERTIFIED. This gate never
// receives, and never emits, a word that reads as a clearance.
const ALLOWED_STATUS = [
  'HOLD',
  'HUMAN_REVIEW_REQUIRED',
  'REVIEW_COMPLETE_NO_DISCREPANCIES_FOUND',
  'REJECT_INTAKE',
];

const out = [];

for (const item of $input.all()) {
  const j = item.json;

  const missing = REQUIRED.filter(
    (k) => j[k] === undefined || j[k] === null || j[k] === ''
  );
  if (missing.length) {
    throw new Error(
      'Approval gate input invalid - missing required field(s): ' +
      missing.join(', ') +
      '. The gate refuses to open on incomplete input.'
    );
  }

  if (!ALLOWED_STATUS.includes(j.system_status)) {
    throw new Error(
      'Approval gate input invalid - system_status ' + JSON.stringify(j.system_status) +
      ' is not in the allowed vocabulary: ' + ALLOWED_STATUS.join(', ') +
      '. Clearance-shaped words (PASS, CLEARED, APPROVED, CERTIFIED) are rejected by design.'
    );
  }

  const confidence = Number(j.confidence);
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
    throw new Error(
      'Approval gate input invalid - confidence must be a number between 0 and 1. Received: ' +
      JSON.stringify(j.confidence)
    );
  }

  for (const k of ['discrepancies', 'missing_information', 'evidence']) {
    if (!Array.isArray(j[k])) {
      throw new Error(
        'Approval gate input invalid - "' + k +
        '" must be an array. Send [] when there are none; never omit it.'
      );
    }
  }

  // An empty evidence array alongside asserted discrepancies is itself a defect:
  // a finding with no evidence locator cannot be reviewed.
  if (j.discrepancies.length > 0 && j.evidence.length === 0) {
    throw new Error(
      'Approval gate input invalid - ' + j.discrepancies.length +
      ' discrepancy/discrepancies were asserted with zero evidence items. ' +
      'Every finding must carry an evidence locator before a human is asked to review it.'
    );
  }

  out.push({
    json: {
      ...j,
      confidence,
      gate_input_validated_at: new Date().toISOString(),
    },
  });
}

return out;

// Builds the human-readable packet the reviewer actually sees, and a stable
// fingerprint of it so the recorded decision binds to what was shown.

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('00000000' + h.toString(16)).slice(-8);
}

const sev = (d) => String(d.severity || 'unspecified').toLowerCase();
const out = [];

for (const item of $input.all()) {
  const j = item.json;

  const critical = j.discrepancies.filter((d) => sev(d) === 'critical');
  const major    = j.discrepancies.filter((d) => sev(d) === 'major');
  const minor    = j.discrepancies.filter((d) => sev(d) === 'minor');
  const blocking = j.missing_information.filter((m) => m.blocking === true);

  const fmtDisc = (d, i) =>
    '  ' + (i + 1) + '. [' + sev(d).toUpperCase() + '] ' + (d.field || 'unspecified field') +
    '\n     observed: ' + (d.observed ?? 'n/a') +
    '\n     expected: ' + (d.expected ?? 'n/a') +
    '\n     standard: ' + (d.standard || 'NOT CITED - treat as unsupported') +
    '\n     read confidence: ' + (d.confidence || 'unstated');

  const fmtMissing = (m, i) =>
    '  ' + (i + 1) + '. ' + (m.item || 'unspecified') +
    (m.blocking === true ? '  [BLOCKING]' : '') +
    (m.why_it_matters ? '\n     why: ' + m.why_it_matters : '');

  const fmtEvidence = (e, i) =>
    '  ' + (i + 1) + '. ' + (e.discrepancy_id || 'unlinked') +
    ' @ ' + (e.locator || 'no locator') +
    '\n     legibility: ' + (e.legibility || 'unstated') +
    (e.document_sha256 ? '\n     document: ' + e.document_sha256 : '');

  const rha = j.recommended_human_action || {};
  const steps = Array.isArray(rha.steps) ? rha.steps : [];
  const doNot = Array.isArray(rha.do_not) ? rha.do_not : [];

  const packet_text = [
    'HUMAN APPROVAL & EXCEPTION GATE',
    'This gate records a review decision. It does not certify, clear, sign,',
    'tender, send to a client, or take any operational action.',
    '',
    'Workflow:          ' + j.workflow_name,
    'Submission ID:     ' + j.submission_id,
    'Review type:       ' + j.review_type,
    'System status:     ' + j.system_status,
    'System confidence: ' + j.confidence,
    '',
    'DISCREPANCIES (' + j.discrepancies.length + ' total - ' +
      critical.length + ' critical, ' + major.length + ' major, ' + minor.length + ' minor)',
    j.discrepancies.length ? j.discrepancies.map(fmtDisc).join('\n') : '  none asserted',
    '',
    'MISSING INFORMATION (' + j.missing_information.length + ' total - ' +
      blocking.length + ' blocking)',
    j.missing_information.length ? j.missing_information.map(fmtMissing).join('\n') : '  none asserted',
    '',
    'EVIDENCE (' + j.evidence.length + ' items)',
    j.evidence.length ? j.evidence.map(fmtEvidence).join('\n') : '  none supplied',
    '',
    'RECOMMENDED HUMAN ACTION',
    '  ' + (rha.summary || 'none supplied'),
    steps.length ? steps.map((s, i) => '  ' + (i + 1) + '. ' + s).join('\n') : '',
    doNot.length ? '\n  DO NOT:\n' + doNot.map((s) => '   - ' + s).join('\n') : '',
    rha.required_qualification ? '\n  Reviewer must hold: ' + rha.required_qualification : '',
  ].join('\n');

  out.push({
    json: {
      ...j,
      packet_text,
      counts: {
        discrepancies: j.discrepancies.length,
        critical: critical.length,
        major: major.length,
        minor: minor.length,
        missing_information: j.missing_information.length,
        blocking_missing_information: blocking.length,
        evidence: j.evidence.length,
      },
      // Change-detection aid that binds the decision to the packet shown.
      // Not a cryptographic seal - the append-only audit store is the
      // authoritative integrity control.
      packet_fingerprint_fnv1a: fnv1a(packet_text),
      approval_id: 'APR-' + j.submission_id + '-' + fnv1a(packet_text),
      gate_opened_at: new Date().toISOString(),
      gate_version: '1.0.0-draft',
    },
  });
}

return out;

// Records reviewer identity, decision, timestamp and comments.
// Rejects anonymous, unqualified, or unexplained decisions.

const ALLOWED_DECISIONS = [
  'Acknowledge and continue review',
  'Return for correction',
  'Escalate',
];

const out = [];

for (const item of $input.all()) {
  const form = item.json;
  const packet = $('Build Review Packet').first().json;

  const reviewer_name = String(form['Reviewer name'] || '').trim();
  const reviewer_role = String(form['Reviewer role or qualification'] || '').trim();
  const decision      = String(form['Decision'] || '').trim();
  const comments      = String(form['Comments'] || '').trim();

  if (!reviewer_name) {
    throw new Error('Gate cannot record a decision without a named reviewer.');
  }
  if (!reviewer_role) {
    throw new Error(
      'Gate cannot record a decision without the reviewer role/qualification - ' +
      'it is the competence evidence for this review type.'
    );
  }
  if (!ALLOWED_DECISIONS.includes(decision)) {
    throw new Error('Unrecognised reviewer decision: ' + JSON.stringify(decision));
  }
  if (decision !== 'Acknowledge and continue review' && !comments) {
    throw new Error(
      'Comments are mandatory for the decision "' + decision + '". ' +
      'Record the reason on the audit trail.'
    );
  }

  out.push({
    json: {
      approval_record: {
        approval_id: packet.approval_id,
        gate_version: packet.gate_version,

        // What was reviewed
        workflow_name: packet.workflow_name,
        submission_id: packet.submission_id,
        review_type: packet.review_type,
        system_status: packet.system_status,
        system_confidence: packet.confidence,
        counts: packet.counts,
        packet_fingerprint_fnv1a: packet.packet_fingerprint_fnv1a,

        // Who decided
        reviewer_name,
        reviewer_role,
        // The default n8n form is unauthenticated: the name is asserted by the
        // person filling it in, not proven. Front the form with SSO/proxy auth
        // (or swap the Wait node for an authenticated sendAndWait channel) and
        // set this to "authenticated" before this gate carries real reviews.
        reviewer_identity_assurance: 'self_declared',

        // What they decided
        decision,
        comments: comments || null,
        gate_opened_at: packet.gate_opened_at,
        decided_at: new Date().toISOString(),
      },
    },
  });
}

return out;

// Boundary assertion. This node exists so the "does nothing operational"
// property is enforced in code rather than left as a comment.

const out = [];

for (const item of $input.all()) {
  const rec = item.json.approval_record;

  const gate_result = {
    ...rec,

    // Constant, in every branch, for every decision. A reviewer acknowledging
    // a review is not an authorisation to act on it.
    authorizes_operational_action: false,
    next_step_owner: 'human',

    boundary: {
      certifies: false,
      clears: false,
      signs: false,
      tenders: false,
      sends_to_client: false,
      releases_shipment: false,
      dispatches_work: false,
      makes_financial_commitment: false,
    },

    boundary_statement:
      'This record captures a human review decision only. It does not certify, ' +
      'clear, sign, tender, send to a client, release a shipment, dispatch work, ' +
      'or commit funds. Any such action requires a separate, explicitly authorised ' +
      'step performed by a qualified person.',
  };

  // Fail loudly rather than silently emitting a permissive record.
  for (const [k, v] of Object.entries(gate_result.boundary)) {
    if (v !== false) {
      throw new Error('Gate boundary violated: "' + k + '" was set to ' + JSON.stringify(v));
    }
  }
  if (gate_result.authorizes_operational_action !== false) {
    throw new Error('Gate boundary violated: authorizes_operational_action was not false.');
  }

  out.push({ json: { gate_result } });
}

return out;
